package com.cuupe.backend.modules.settings.controller;
import com.cuupe.backend.common.Result; import com.cuupe.backend.modules.audit.service.AuditLogService; import com.cuupe.backend.modules.settings.entity.PromptVersion; import com.cuupe.backend.modules.settings.mapper.PromptVersionMapper; import com.cuupe.backend.modules.user.security.UserLoginByPassword; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/workspaces/{workspaceId}/settings/prompts") @RequiredArgsConstructor public class PromptVersionController { private final PromptVersionMapper mapper; private final AuditLogService auditLogService;
 @GetMapping public Result<List<PromptVersion>> list(@PathVariable Long workspaceId,Authentication auth){return Result.success(mapper.findByWorkspace(workspaceId,userId(auth)));}
 @PostMapping public Result<PromptVersion> create(@PathVariable Long workspaceId,@Valid @RequestBody PromptRequest request,Authentication auth){PromptVersion p=new PromptVersion();p.setWorkspaceId(workspaceId);p.setCreatedBy(userId(auth));p.setScene(request.scene());p.setVersionNo(request.versionNo());p.setSystemPrompt(request.systemPrompt());p.setStatus(request.status());mapper.insert(p);auditLogService.record(workspaceId,null,userId(auth),"PROMPT_VERSION_CREATED","PROMPT_VERSION",p.getId());return Result.success(p);}
 @PatchMapping("/{id}") public Result<PromptVersion> update(@PathVariable Long workspaceId,@PathVariable Long id,@Valid @RequestBody PromptRequest request,Authentication auth){PromptVersion p=new PromptVersion();p.setId(id);p.setWorkspaceId(workspaceId);p.setVersionNo(request.versionNo());p.setSystemPrompt(request.systemPrompt());p.setStatus(request.status());mapper.update(p);auditLogService.record(workspaceId,null,userId(auth),"PROMPT_VERSION_UPDATED","PROMPT_VERSION",id);return Result.success(p);}
 private Long userId(Authentication a){return ((UserLoginByPassword)a.getPrincipal()).getId();} public record PromptRequest(@NotBlank String scene,@NotBlank String versionNo,@NotBlank String systemPrompt,@NotBlank String status){}
}
